\begin{aligned}
\mathrm{S}_{\mathrm{n}} &=\mathrm{u}+\frac{\mathrm{a}}{2}(2 \mathrm{n}-1) \\
5 &=\mathrm{u}+\frac{\mathrm{a}}{2}(2 \times 1-1) \\
5 &=\mathrm{u}+\frac{\mathrm{a}}{2} \\
2 &=\mathrm{u}+\frac{\mathrm{a}}{2}(2 \times 3-1) \\
2 &=\mathrm{u}+\frac{5}{2} \mathrm{a}
\end{aligned}

